 4	final class KruskalMST {
 5	    private KruskalMST() {
 6	        // Utility class.
 7	    }
 8	
 9	    public static int kruskalsMST(int vertexCount, int[][] rawEdges) {
10	        return minimumSpanningTreeCost(Graph.fromEdgeMatrix(vertexCount, rawEdges));
11	    }
12	
13	    static int minimumSpanningTreeCost(Graph graph) {
14	        return findMinimumSpanningTree(graph).totalWeight();
15	    }
16	
17	    static MinimumSpanningTreeResult findMinimumSpanningTree(Graph graph) {
18	        if (graph == null) {
19	            throw new IllegalArgumentException("Graph must not be null.");
20	        }
21	
22	        List<Edge> sortedEdges = graph.edges().stream()
23	            .sorted()
24	            .toList();
25	
26	        DisjointSet disjointSet = new DisjointSet(graph.vertexCount());
27	        List<Edge> selectedEdges = new ArrayList<>();
28	        int totalWeight = 0;
29	
30	        for (Edge edge : sortedEdges) {
31	            if (disjointSet.union(edge.from(), edge.to())) {
32	                selectedEdges.add(edge);
33	                totalWeight += edge.weight();
34	                if (selectedEdges.size() == graph.vertexCount() - 1) {
35	                    break;
36	                }
37	            }
38	        }
39	
40	        return new MinimumSpanningTreeResult(
41	            totalWeight,
42	            selectedEdges,
43	            graph.vertexCount() == 0 || selectedEdges.size() == graph.vertexCount() - 1
44	        );
45	    }
46	}

