 3	record Graph(int vertexCount, List<Edge> edges) {
 4	    Graph {
 5	        if (vertexCount < 0) {
 6	            throw new IllegalArgumentException("Vertex count must be non-negative.");
 7	        }
 8	        if (edges == null) {
 9	            throw new IllegalArgumentException("Edges must not be null.");
10	        }
11	
12	        edges = List.copyOf(edges);
13	        validateEdges(vertexCount, edges);
14	    }
15	
16	    static Graph fromEdgeMatrix(int vertexCount, int[][] rawEdges) {
17	        if (rawEdges == null) {
18	            throw new IllegalArgumentException("Edges must not be null.");
19	        }
20	
21	        return new Graph(vertexCount, java.util.Arrays.stream(rawEdges)
22	            .map(Edge::fromMatrixRow)
23	            .toList());
24	    }
25	
26	    private static void validateEdges(int vertexCount, List<Edge> edges) {
27	        for (Edge edge : edges) {
28	            validateVertex(edge.from(), vertexCount);
29	            validateVertex(edge.to(), vertexCount);
30	        }
31	    }
32	
33	    private static void validateVertex(int vertex, int vertexCount) {
34	        if (vertex < 0 || vertex >= vertexCount) {
35	            throw new IllegalArgumentException(
36	                "Vertex " + vertex + " is out of bounds for graph with " + vertexCount + " vertices."
37	            );
38	        }
39	    }
40	}

